import Darwin
func reference(_ jobs: [Job], limit: Int) -> [Int] {
    var queue = jobs
    var order: [Int] = []
    while !queue.isEmpty {
        let job = queue.removeFirst()
        if job.cost > limit {
            queue.append(Job(id: job.id, cost: job.cost / 2))
            queue.append(Job(id: job.id, cost: job.cost - job.cost / 2))
        } else {
            order.append(job.id)
        }
    }
    return order
}
let inputs: [[Job]] = [[], [Job(id: 1, cost: 3)], [Job(id: 1, cost: 40), Job(id: 2, cost: 1)],
                       (0..<500).map { Job(id: $0, cost: ($0 * 37) % 50) }]
for jobs in inputs {
    for limit in [0, 1, 10, 100] where !(limit == 0 && jobs.contains { $0.cost > 0 }) {
        guard schedule(jobs, limit: limit) == reference(jobs, limit: limit) else {
            print("order differs for \(jobs.count) jobs, limit \(limit)"); exit(1)
        }
    }
}
print("equivalent")
