import pathlib, re, sys
for p in pathlib.Path("Sources").rglob("*.swift"):
    lines = p.read_text().splitlines()
    for i, line in enumerate(lines):
        code = line.split("//")[0]
        if re.search(r"withUnsafe|Unsafe(Mutable)?(Raw)?BufferPointer|unsafe ", code):
            if "SAFETY" not in "\n".join(lines[max(0, i - 4):i + 1]):
                sys.exit(f"{p}:{i + 1}: unsafe code without a PERF/SAFETY comment")
